package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.special.Beta;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FDistribution.isSupportLowerBoundInclusive()
 */
public class FDistribution_isSupportLowerBoundInclusive_TriageGen0Test {

    @Test
    public void testIsSupportLowerBoundInclusive() throws NotStrictlyPositiveException {
        // Given: An FDistribution instance with valid degrees of freedom
        double numeratorDegreesOfFreedom = 5.0;
        double denominatorDegreesOfFreedom = 10.0;
        FDistribution distribution = new FDistribution(numeratorDegreesOfFreedom, denominatorDegreesOfFreedom);

        // When: Calling isSupportLowerBoundInclusive()
        boolean result = distribution.isSupportLowerBoundInclusive();

        // Then: It should return true as per the implementation
        Assert.assertTrue("isSupportLowerBoundInclusive should return true for FDistribution", result);
    }

    @Test
    public void testIsSupportLowerBoundInclusiveWithAccuracy() throws NotStrictlyPositiveException {
        // Given: An FDistribution instance with custom inverseCumAccuracy
        double numeratorDegreesOfFreedom = 2.0;
        double denominatorDegreesOfFreedom = 3.0;
        double inverseCumAccuracy = 1e-10;
        FDistribution distribution = new FDistribution(numeratorDegreesOfFreedom, denominatorDegreesOfFreedom, inverseCumAccuracy);

        // When: Calling isSupportLowerBoundInclusive()
        boolean result = distribution.isSupportLowerBoundInclusive();

        // Then: It should return true
        Assert.assertTrue("isSupportLowerBoundInclusive should return true even with custom accuracy", result);
    }

    @Test(expected = NotStrictlyPositiveException.class)
    public void testConstructorInvalidDegreesOfFreedom() throws NotStrictlyPositiveException {
        // This test ensures the constructor works and we can reach the method after valid construction
        // We use it to verify the context of the class
        new FDistribution(-1.0, 10.0);
    }
}
